import { ethers } from "ethers";
import fs from "fs";
import path from "path";

const pk = fs.readFileSync(path.join(process.env.HOME, ".bridgekitty", ".env"), "utf-8").match(/PRIVATE_KEY=(.+)/)[1].trim();

const bridges = [
  {
    name: "Arbitrum → Base",
    chainId: 42161,
    rpcs: ["https://arb1.arbitrum.io/rpc", "https://arbitrum.drpc.org"],
    approval: {
      to: "0xaf88d065e77c8cC2239327C5EDb3A432268e5831",
      data: "0x095ea7b3000000000000000000000000e35e9842fceaca96570b734083f4a58e8f7c5f2a00000000000000000000000000000000000000000000000000000000004c1c60",
    },
    bridge: {
      to: "0xe35e9842fceaCA96570B734083f4a58e8F7C5f2A",
      data: "",
    },
  },
  {
    name: "Optimism → Base",
    chainId: 10,
    rpcs: ["https://mainnet.optimism.io", "https://optimism.drpc.org"],
    approval: {
      to: "0x0b2C639c533813f4Aa9D7837CAf62653d097Ff85",
      data: "0x095ea7b30000000000000000000000006f26bf09b1c792e3228e5467807a900a503c028100000000000000000000000000000000000000000000000000000000004c4758",
    },
    bridge: {
      to: "0x6f26Bf09B1C792e3228e5467807a900A503c0281",
      data: "",
    },
  },
  {
    name: "Polygon → Base",
    chainId: 137,
    rpcs: ["https://polygon-bor-rpc.publicnode.com", "https://polygon.drpc.org"],
    approval: {
      to: "0x3c499c542cEF5E3811e1192ce70d8cC03d5c3359",
      data: "0x095ea7b30000000000000000000000009295ee1d8c5b022be115a2ad3c30c72e34e7f0960000000000000000000000000000000000000000000000000000000000726140",
    },
    bridge: {
      to: "0x9295ee1d8C5b022Be115A2AD3c30C72E34e7F096",
      data: "",
    },
  },
];

async function getProvider(rpcs, chainId) {
  for (const rpc of rpcs) {
    try { const p = new ethers.JsonRpcProvider(rpc, chainId); await p.getBlockNumber(); return p; } catch { continue; }
  }
  throw new Error(`All RPCs failed for chain ${chainId}`);
}

async function bridgeOne(b) {
  console.log(`\n========== ${b.name} ==========`);
  const provider = await getProvider(b.rpcs, b.chainId);
  const wallet = new ethers.Wallet(pk, provider);
  let nonce = await provider.getTransactionCount(wallet.address, "latest");

  console.log("Approval...");
  const a = await wallet.sendTransaction({ to: b.approval.to, data: b.approval.data, value: 0n, nonce: nonce++ });
  console.log(`Tx: ${a.hash}`);
  await a.wait(1);
  console.log("OK.");

  console.log("Bridge...");
  const tx = await wallet.sendTransaction({ to: b.bridge.to, data: b.bridge.data, value: 0n, gasLimit: 300000n, nonce: nonce++ });
  console.log(`Tx: ${tx.hash}`);
  const r = await tx.wait(1);
  console.log(`Confirmed block ${r.blockNumber} (gas: ${r.gasUsed})`);
  return tx.hash;
}

async function main() {
  const results = [];
  for (const b of bridges) {
    try {
      const hash = await bridgeOne(b);
      results.push({ name: b.name, status: "SUCCESS", hash });
    } catch (err) {
      results.push({ name: b.name, status: "FAILED", error: err.message.slice(0, 120) });
    }
  }
  console.log("\n========== RESULTS ==========");
  for (const r of results) console.log(`${r.name}: ${r.status}${r.hash ? " " + r.hash : ""}${r.error ? " " + r.error : ""}`);
}

main().catch((err) => { console.error("FATAL:", err.message); process.exit(1); });
